package studyfix;
import studyfix.assignment.transport.AssignmentTcpServer;
import studyfix.assignment.persistence.*;
import java.nio.file.*;
import java.util.*;
import static studyfix.ClassroomIntegrationTest.*;
import static studyfix.assignment.protocol.AssignmentJson.*;
public final class OjImportIntegrationTest {
 static byte[] samplePackage(byte[] original,int count,String prefix,int weekCount,boolean declareCounts)throws Exception{
  Map<String,byte[]> source=new LinkedHashMap<>();try(var in=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(original),java.nio.charset.StandardCharsets.UTF_8)){java.util.zip.ZipEntry e;while((e=in.getNextEntry())!=null)if(!e.isDirectory())source.put(e.getName(),in.readAllBytes());}
  String manifestPath=source.keySet().stream().filter(p->p.endsWith("/manifest.json")).findFirst().orElseThrow(),root=manifestPath.replaceFirst("manifest.json$","");var oldManifest=object(new String(source.get(manifestPath),java.nio.charset.StandardCharsets.UTF_8));var first=map(list(oldManifest.get("problems")).get(0));String oldDir=root+"problems/"+text(first,"id","")+"/";
  Map<String,byte[]> output=new LinkedHashMap<>();List<Map<String,Object>> headers=new ArrayList<>(),weeks=new ArrayList<>();for(int n=1;n<=weekCount;n++)weeks.add(mapOf("week_number",n,"title","Imported Week "+n,"learning_topics","Import test","problem_ids",new ArrayList<String>()));
  for(int i=1;i<=count;i++){String code=prefix+String.format(Locale.ROOT,"%03d",i),dir=root+"problems/"+code+"/";int week=weekCount==0?0:(i-1)%weekCount+1;var header=new LinkedHashMap<>(first);header.put("id",code);headers.add(header);for(var file:source.entrySet())if(file.getKey().startsWith(oldDir))output.put(dir+file.getKey().substring(oldDir.length()),file.getValue());var meta=object(new String(source.get(oldDir+"problem.json"),java.nio.charset.StandardCharsets.UTF_8));meta.put("id",code);meta.put("week",week);meta.put("week_title",week==0?"Unassigned":"Imported Week "+week);output.put(dir+"problem.json",stringify(meta).getBytes(java.nio.charset.StandardCharsets.UTF_8));if(week>0){@SuppressWarnings("unchecked")var ids=(List<String>)weeks.get(week-1).get("problem_ids");ids.add(code);}}
  var manifest=mapOf("problems",headers,"categories_enabled",false);if(declareCounts){manifest.put("total_problems",count);manifest.put("week_count",weekCount);}output.put(root+"manifest.json",stringify(manifest).getBytes(java.nio.charset.StandardCharsets.UTF_8));if(weekCount>0)output.put(root+"weeks.json",stringify(weeks).getBytes(java.nio.charset.StandardCharsets.UTF_8));
  var bytes=new java.io.ByteArrayOutputStream();try(var out=new java.util.zip.ZipOutputStream(bytes)){for(var file:output.entrySet()){out.putNextEntry(new java.util.zip.ZipEntry(file.getKey()));out.write(file.getValue());out.closeEntry();}}return bytes.toByteArray();
 }
 static Map<String,Object> commit(String base,String token,Map<String,Object> preview)throws Exception{var response=call(base,"/api/oj/import/commit",token,mapOf("previewId",preview.get("previewId"),"sha256",map(preview.get("report")).get("sha256")));if(response.status()!=200)throw new AssertionError("Commit "+response.body());return map(response.body().get("data"));}
 static Map<String,Object> preview(String base,String token,byte[] bytes)throws Exception{var response=ProblemBuilderIntegrationTest.binary(base,token,"/api/oj/import/preview",bytes);if(response.statusCode()!=200)throw new AssertionError("Preview HTTP "+response.statusCode());return map(object(new String(response.body(),java.nio.charset.StandardCharsets.UTF_8)).get("data"));}
 public static void main(String[] args)throws Exception{
  System.setProperty("studyfix.legacy.sqlite","true");System.setProperty("studyfix.management.db","sqlite");System.setProperty("studyfix.test.accounts",Path.of("test/fixtures/accounts.tsv").toAbsolutePath().toString());System.setProperty("studyfix.screen.port","0");System.setProperty("studyfix.web.port","0");System.setProperty("studyfix.web.ws.port","0");Path temp=Files.createTempDirectory(Path.of("build"),"oj-import-");byte[] zip=Files.readAllBytes(Path.of("private/catalogs/CodeBank_Java_100_OJ_Complete.zip"));
  try(Server core=new Server(0,temp.resolve("core.db"));AssignmentTcpServer assignments=new AssignmentTcpServer(core.gateway(),temp.resolve("learning.db"),0,8,1,"unused");WebGatewayServer web=new WebGatewayServer(core,assignments)){
   core.start();assignments.start();web.start();String base="http://127.0.0.1:"+web.port(),teacher=login(base,"teacher","Teacher123!"),student=login(base,"student1","Student123!");Identity owner=core.store().login("teacher","Teacher123!".toCharArray());AssignmentRepository repo=new AssignmentRepository(temp.resolve("learning.db"));var bank=new QuestionBankRepository(repo);int initialBankCount=bank.list(owner).size();
   check(ProblemBuilderIntegrationTest.binary(base,student,"/api/oj/import/preview",zip).statusCode()==403,"Student cannot import OJ");check(ProblemBuilderIntegrationTest.binary(base,teacher,"/api/oj/import/preview","bad zip".getBytes()).statusCode()==400,"malformed ZIP is a client error");var preview=preview(base,teacher,zip);check(integer(map(preview.get("report")),"tests",0)==316,"preview counts real test files");check(bank.list(owner).size()==initialBankCount,"preview does not mutate bank");
   var request=mapOf("previewId",preview.get("previewId"),"sha256",map(preview.get("report")).get("sha256"));check(call(base,"/api/oj/import/commit",student,request).status()==403,"Student cannot consume Teacher ticket");check(call(base,"/api/oj/import/commit",teacher,request).status()==200,"confirmed import commits");check(bank.list(owner).size()==initialBankCount+100,"UI import adds 100 without deleting existing bank");
   var second=preview(base,teacher,zip);var repeated=call(base,"/api/oj/import/commit",teacher,mapOf("previewId",second.get("previewId"),"sha256",map(second.get("report")).get("sha256")));check(integer(map(repeated.body().get("data")),"reused",0)==100,"HTTP import idempotence");check(new QuestionWeekRepository(repo).list(owner).size()==12,"HTTP import keeps 12 Weeks");
   check(call(base,"/private/catalogs/CodeBank_Java_100_OJ_Complete.zip","",null).status()==404,"private reference package not web-static");
   byte[] single=samplePackage(zip,1,"MY_TASK-",0,true);var onePreview=preview(base,teacher,single);check(integer(map(onePreview.get("report")),"problems",0)==1&&integer(map(onePreview.get("report")),"weeks",-1)==0,"one custom-code problem accepted without Weeks");var oneResult=commit(base,teacher,onePreview);check(integer(oneResult,"inserted",0)==1&&integer(oneResult,"problems",0)==1&&integer(oneResult,"weeks",-1)==0,"commit reports actual one problem, zero Weeks");
   var weeksRepo=new QuestionWeekRepository(repo);String firstWeek=text(weeksRepo.list(owner).get(0),"id","");var membersBefore=weeksRepo.exerciseIds(firstWeek,owner);byte[] small=samplePackage(zip,7,"SMALL_",1,false);var seven=commit(base,teacher,preview(base,teacher,small));check(integer(seven,"inserted",0)==7&&integer(seven,"problems",0)==7,"seven problems accepted with counts inferred from content");check(weeksRepo.exerciseIds(firstWeek,owner).containsAll(membersBefore),"import into existing Week retains all previous members");
   byte[] bulk=samplePackage(zip,150,"BULK_",21,true);var bulkPreview=preview(base,teacher,bulk);check(integer(map(bulkPreview.get("report")),"problems",0)==150&&integer(map(bulkPreview.get("report")),"weeks",0)==21,"more than 100 problems and 12 Weeks accepted");var bulkResult=commit(base,teacher,bulkPreview);check(integer(bulkResult,"inserted",0)==150&&integer(bulkResult,"weeks",0)==21,"bulk commit reports dynamic counts");check(bank.list(owner).size()==initialBankCount+258,"small and bulk imports preserve every unrelated question");check(integer(commit(base,teacher,preview(base,teacher,bulk)),"reused",0)==150&&bank.list(owner).size()==initialBankCount+258,"bulk repeat has no duplicates");
   String oldId=bank.list(owner).stream().filter(row->"SMALL_001".equals(row.get("displayCode"))).map(row->text(row,"id","")).findFirst().orElseThrow();var oldSource=repo.getExercise(oldId);var beforeVersion=weeksRepo.exerciseIds(firstWeek,owner);commit(base,teacher,preview(base,teacher,samplePackage(zip,1,"SMALL_",1,true)));String newId=bank.list(owner).stream().filter(row->"SMALL_001".equals(row.get("displayCode"))).map(row->text(row,"id","")).findFirst().orElseThrow();check(!newId.equals(oldId)&&repo.getExercise(oldId).equals(oldSource),"same code creates immutable version without overwriting old source/tests");check(weeksRepo.exerciseIds(firstWeek,owner).contains(newId)&&weeksRepo.exerciseIds(firstWeek,owner).size()==beforeVersion.size(),"Week points to new version without losing other questions");
   try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+temp.resolve("core.db").toAbsolutePath());var p=c.prepareStatement("INSERT INTO users(user_id,username,password_hash,display_name,role) VALUES(?,?,?,?,?)")){p.setString(1,UUID.randomUUID().toString());p.setString(2,"other_teacher");p.setString(3,Passwords.hash("OtherTeacher123!".toCharArray()));p.setString(4,"Other Teacher");p.setString(5,"TEACHER");p.executeUpdate();}
   String other=login(base,"other_teacher","OtherTeacher123!");byte[] changed=Arrays.copyOf(zip,zip.length+1);changed[zip.length-2]=1;changed[zip.length-1]=0;changed[zip.length]='X';var foreign=preview(base,other,changed);check(call(base,"/api/oj/import/commit",other,mapOf("previewId",foreign.get("previewId"),"sha256",map(foreign.get("report")).get("sha256"))).status()==403,"new ZIP hash cannot steal another Teacher snapshots");check(bank.list(owner).size()==initialBankCount+258,"rejected foreign import rolls back bank changes");
   byte[] empty=samplePackage(zip,0,"EMPTY_",0,true);check(ProblemBuilderIntegrationTest.binary(base,teacher,"/api/oj/import/preview",empty).statusCode()==400,"empty package has no definitions to import");
   String modules=System.getenv("STUDYFIX_BUILDER_BROWSER_MODULES");if(modules!=null&&!modules.isBlank()){Files.write(temp.resolve("one.zip"),single);Files.write(temp.resolve("bulk.zip"),bulk);var command=new ProcessBuilder("C:/Program Files/nodejs/node.exe",Path.of("../web-client/tests/oj_import_browser.cjs").toAbsolutePath().toString(),base,temp.toAbsolutePath().toString()).inheritIO();command.environment().put("STUDYFIX_BROWSER_TEST_MODULES",modules);Process browser=command.start();if(!browser.waitFor(90,java.util.concurrent.TimeUnit.SECONDS)){browser.destroyForcibly();throw new AssertionError("OJ import browser timeout");}check(browser.exitValue()==0,"variable-size OJ import real Chrome");}
  }System.out.println("OjImportIntegrationTest PASS: real HTTP arbitrary counts (1/7/100/150), custom codes, optional/21 Weeks, additive preservation, versioning, idempotence, privacy and rollback.");
 }
}
